    kind: "IMAGE" | "DOCUMENT" | "FILE" | "VOICE_NOTE" | "VIDEO";
    state: "INTENT_CREATED" | "VERIFYING" | "READY" | "QUARANTINED" | "REJECTED" | "EXPIRED" | "DELETED";
    stateReason: string | null;
    securityProfile: "PRIVATE_E2EE" | "MANAGED";
