  /** POST /v1/numbers/kyc/cases/{caseId}/evidence (numbers.kyc.manage). Content is sealed (AES-256-GCM, bound to the evidence id) and stored privately; ≤ 5 MiB decoded. The kind must be accepted by a requirement of the case. */
  export type SubmitEvidenceRequest = {
    evidenceKind: EvidenceKind;
    contentType: EvidenceContentType;
    contentBase64: string;
  };
  /** POST /v1/numbers/kyc/cases/{caseId}/submit: every mandatory requirement needs accepted ACTIVE evidence (else MANDATORY_EVIDENCE_MISSING). */
  export type SubmitKycCaseRequest = {
    expectedRevision: Revision;
  };
  /** POST /v1/numbers/assignments/{id}/suspend and POST /v1/admin/number-resources/{id}/suspend: local-first suspension (grants refused and revoked at once, ownership retained), then the provider SUSPEND. */
  export type SuspendRequest = {
    reasonCode: string;
    evidenceRef?: Uuid;
  };
  /** A number's suspension with its restoration checks (each true / false) and outcome. */
  export type Suspension = {
    suspensionId: Uuid;
    numberResourceId: Uuid;
    assignmentId: Uuid;
    source: SuspensionSource;
    reasonCode: string;
    status: SuspensionStatus;
    providerState: SuspensionProviderState;
    suspendedAt: Timestamp;
    restoreRequestedAt?: Timestamp | null;
    restoreBlockedReason?: string | null;
    restoreChecks?: { [key: string]: boolean } | null;
    restoredAt?: Timestamp | null;
    endedReason?: string | null;
    revision: Revision;
  };
  /** The provider route disable: not required (no adapter), PENDING / CONFIRMED / FAILED / UNKNOWN through the durable command executor, UNSUPPORTED by the adapter. */
  export type SuspensionProviderState = "NOT_REQUIRED" | "PENDING" | "CONFIRMED" | "UNSUPPORTED" | "UNKNOWN" | "FAILED";
  /** Who suspended a number: its customer (CUSTOMER / ORGANIZATION, lifted by the customer) or an operator, the risk policy or a provider state drift (lifted by an operator only). */
  export type SuspensionSource = "CUSTOMER" | "ORGANIZATION" | "OPERATOR" | "RISK" | "PROVIDER";
  /** A suspension's state. */
  export type SuspensionStatus = "SUSPENDED" | "RESTORING" | "RESTORED" | "ENDED";
  /** RFC 3339 UTC timestamp. */
  export type Timestamp = string;
  /** POST /v1/numbers/assignments/{id}/transfer (Idempotency-Key required): within the same legal owner only. Same class: a routing revision. Another class of the same owner: the ACTIVE assignment closes (TRANSFERRED_INTERNALLY) and a successor opens, admitted on a re-evaluated eligibility decision of the new class and activated in the same transaction. A different owner is … */
  export type TransferAssignmentRequest = {
    ownershipClass: OwnershipClass;
    ownerPrincipalId?: Uuid;
    routing: RoutingTargets;
    eligibilityDecisionId?: Uuid;
    expectedRoutingRevision: Revision;
  };
  /** The outcome of an internal transfer. */
  export type TransferResult = {
    transferKind: "RETARGET" | "RECLASSIFY";
    assignment: DcnAssignment;
    predecessor: DcnAssignment | null;
  };
  /** POST /v1/numbers/assignments/{id}/routing: a new routing revision (same class, same owner). expectedRoutingRevision is the profile revision the caller saw (VERSION_CONFLICT otherwise). */
  export type UpdateRoutingRequest = {
    expectedRoutingRevision: Revision;
    routing: RoutingTargets;
  };
  /** What a usage record measures (internal provider cost evidence, never a customer price). */
  export type UsageKind = "NUMBER_RENTAL" | "NUMBER_SETUP" | "NUMBER_RENEWAL" | "VOICE_INBOUND_SECONDS" | "VOICE_OUTBOUND_SECONDS" | "SMS_INBOUND_SEGMENTS" | "SMS_OUTBOUND_SEGMENTS" | "PORTING";
  /** GET /v1/numbers/usage: quantities of the caller's scope per number and kind (no costs). */
  export type UsageSummaryList = {
    data: Array<{
        numberResourceId: Uuid;
        assignmentId?: Uuid | null;
        usageKind: UsageKind;
        unit: "MONTH" | "EVENT" | "SECOND" | "SEGMENT";
        quantity: number;
        records: number;
        finalRecords: number;
      }>;
    from: Timestamp;
    to: Timestamp;
  };
  /** Lower-case hyphenated UUID. */
  export type Uuid = string;
  /** Who verified: the deterministic test adapter (never in staging / production), the audited manual reviewer, or the system (lifecycle steps). */
  export type VerifierKind = "DETERMINISTIC" | "MANUAL" | "SYSTEM";
  /** Voice routing target: opaque CF Meet ids of Calling / enterprise constructs (principal, professional identity, endpoint, extension, ring group, queue, IVR, department, shared team, voicemail, approved forwarding), never SIP or provider data. The kinds a number may use are bounded by its ownership class (TARGET_NOT_PERMITTED). */
  export type VoiceTargetKind = "NONE" | "PRINCIPAL" | "CALLING_ENDPOINT" | "ENTERPRISE_EXTENSION" | "ENTERPRISE_RING_GROUP" | "ENTERPRISE_QUEUE" | "ENTERPRISE_IVR" | "ENTERPRISE_DEPARTMENT" | "PROFESSIONAL_IDENTITY" | "SHARED_TEAM" | "VOICEMAIL" | "APPROVED_FORWARDING";

