export namespace PrivacyRelay {
  /** Immutable Privacy Relay evidence event types. */
  export type AuditEventType = "CONTEXT_CREATED" | "CONTEXT_UPDATED" | "CONTEXT_PARTICIPANTS_CHANGED" | "CONTEXT_SUSPENDED" | "CONTEXT_RESUMED" | "CONTEXT_REVOKED" | "CONTEXT_COMPLETED" | "CONTEXT_EXPIRED" | "RELAY_SESSION_CREATED" | "RELAY_SESSION_UPDATED" | "RELAY_SESSION_SUSPENDED" | "RELAY_SESSION_RESUMED" | "RELAY_SESSION_REVOKED" | "RELAY_SESSION_COMPLETED" | "RELAY_SESSION_EXPIRED" | "ENFORCEMENT_REQUESTED" | "ENFORCEMENT_APPLIED" | "ENFORCEMENT_FAILED" | "RELAY_NUMBER_ASSIGNED" | "RELAY_NUMBER_RELEASED" | "RELAY_NUMBER_COOLDOWN_STARTED";
  /** Outcome of a communication authorization. */
  export type AuthorizationDecision = "AUTHORIZED" | "DENIED";
  /** Safe intent metadata of an authorization request. */
  export type AuthorizationPurpose = "CALL_CREATE" | "CALL_TRANSFER" | "CHECK";
  /** Normalized platform reason of a decision (no consumer-specific reasons). */
  export type AuthorizationReason = "AUTHORIZED" | "FEATURE_DISABLED" | "CONTEXT_NOT_ACTIVE" | "CONTEXT_NOT_STARTED" | "CONTEXT_EXPIRED" | "CONTEXT_REVOKED" | "CONTEXT_SUSPENDED" | "SESSION_NOT_ACTIVE" | "SESSION_NOT_STARTED" | "SESSION_EXPIRED" | "PARTICIPANT_NOT_AUTHORIZED" | "DIRECTION_NOT_ALLOWED" | "CHANNEL_NOT_ALLOWED" | "STRATEGY_NOT_ALLOWED" | "GRACE_POLICY_DENIED" | "CAPABILITY_UNAVAILABLE" | "CONTACT_NOT_VERIFIED" | "CONTACT_VERIFICATION_EXPIRED" | "CONTACT_BLOCKED";
  /** Privacy-safe support / dispute evidence of one protected Call, from Calling's own records. Never a telephone number (raw or masked), Contact Vault material, provider / carrier identifier, provider payload, SIP dialog or credential. */
  export type CallEvidence = {
    callId: Uuid;
    contextId: Uuid | null;
    relaySessionId: Uuid;
    kind: "VOICE" | "VIDEO";
    state: string;
    terminalReason: ("CLEANUP_CONFIRMED" | "PARTICIPATION_ENDED" | "RECONCILIATION_TIMEOUT" | "DECLINED" | "BUSY" | "NO_ANSWER" | "FAILED" | "CANCELLED") | null;
    failureCategory: ("POLICY" | "TARGET_UNAVAILABLE" | "ROUTING" | "TIMEOUT" | "MEDIA" | "NETWORK" | "EXECUTION" | "INTERNAL" | "UNKNOWN") | null;
    requestedAt: Timestamp;
    firstAttemptAt: Timestamp | null;
    ringingAt: Timestamp | null;
    answeredAt: Timestamp | null;
    connectedAt: Timestamp | null;
    endedAt: Timestamp | null;
    connectedDurationMs: number | null;
    durationsAsOf: Timestamp;
    routeClass: ("APPLICATION" | "PUBLIC_NETWORK" | "MIXED" | "PRIVATE_NETWORK") | null;
    attemptCount: number;
    attempts: Array<EvidenceAttempt>;
    participants: Array<EvidenceParticipant>;
    privacyDecisions: Array<EvidenceDecision>;
  };
  /** Communication channel. VOICE is executed; MESSAGING may be declared for the future and is never executed by sections 26-30 (no chat, SMS or provider messaging). */
  export type CommunicationChannel = "VOICE" | "MESSAGING";
  /** Safe representation of a Communication Context. Never a telephone number, provider id, carrier, Contact Vault material, service token or customer credential. */
  export type CommunicationContext = {
    contextId: Uuid;
    externalContextReference: ExternalContextReference;
    version: Version;
    status: CommunicationContextStatus;
    /** Status at read time: EXPIRED once the final validity has passed, even before the expiry worker materializes it. */
    effectiveStatus: CommunicationContextStatus;
    directionPolicy: DirectionPolicy;
    /** Active participants (history: evidence). */
    participants: Array<{
        participantId: Uuid;
        subjectKind: ParticipantSubjectKind;
        principalId?: Uuid;
        contactReferenceId?: Uuid;
        addedInVersion: Version;
        addedAt: Timestamp;
      }>;
    allowedChannels: Array<CommunicationChannel>;
    directions: Array<{
        directionId: Uuid;
        fromParticipantId: Uuid;
        toParticipantId: Uuid;
        channel?: CommunicationChannel;
        addedInVersion: Version;
      }>;
    allowedRelayStrategies: Array<RelayStrategy>;
    startsAt: Timestamp;
    expiresAt: Timestamp;
    graceExpiresAt?: Timestamp;
    policyVersion: string;
    policy: ContextPolicy;
    createdAt: Timestamp;
    updatedAt: Timestamp;
    suspendedAt?: Timestamp;
    completedAt?: Timestamp;
    revokedAt?: Timestamp;
    expiredAt?: Timestamp;
  };
  /** Lifecycle of a Communication Context. REVOKED and EXPIRED are terminal; COMPLETED never returns to ACTIVE or SUSPENDED. */
  export type CommunicationContextStatus = "ACTIVE" | "SUSPENDED" | "REVOKED" | "COMPLETED" | "EXPIRED";
  /** Route an authorization asks for. Only APPLICATION is executable today. */
  export type CommunicationRoute = "APPLICATION" | "PUBLIC_RELAY" | "CALLBACK_RELAY";
  /** A short-lived (default 120 s, at most 300 s) Contact Vault access token, returned once (Cache-Control: no-store). */
  export type ContactAccessGrant = {
    grantId: string;
    /** Compact JWS (EdDSA, typ cf-contact-access+jwt). */
    accessToken: string;
    tokenType: "Bearer";
    authorizationHeader: "X-CF-Contact-Authorization";
    audience: "cfmeet.privacy-relay";
    scopes: Array<ContactScope>;
    expiresAt: Timestamp;
  };
  /** POST /v1/privacy-relay/contact-access-grants (platform credential). Contains no telephone number. */
  export type ContactAccessGrantRequest = {
    scopes: Array<ContactScope>;
  };
  export type ContactAccessGrantResult = {
    grant: ContactAccessGrant;
  };
  /** Contact Vault scopes. A credential can delegate only scopes it holds, and Privacy Relay accepts only scopes its contact delegation trust bundle allows the issuer to delegate. */
  export type ContactScope = "privacy.contacts.read" | "privacy.contacts.write" | "privacy.contacts.verify";
  /** Privacy-safe support evidence: lifecycle, versions, participant and direction history, sessions, recent decisions, audit events and enforcement status. No contact values. */
  export type ContextEvidence = {
    context: CommunicationContext;
    participantHistory: Array<{
        participantId: Uuid;
        subjectKind: ParticipantSubjectKind;
        principalId?: Uuid;
        contactReferenceId?: Uuid;
        addedInVersion: Version;
        addedAt: Timestamp;
        removedInVersion?: Version;
        removedAt?: Timestamp;
      }>;
    directionHistory: Array<{
        directionId: Uuid;
        fromParticipantId: Uuid;
        toParticipantId: Uuid;
        channel?: CommunicationChannel;
        addedInVersion: Version;
        removedInVersion?: Version;
      }>;
    sessions: Array<PrivacyRelaySession>;
    decisions: Array<{
        decisionId: Uuid;
        relaySessionId: Uuid;
        contextVersion: Version;
        relaySessionVersion: Version;
        channel: CommunicationChannel;
        route: CommunicationRoute;
        purpose: AuthorizationPurpose;
        decision: AuthorizationDecision;
        reason: AuthorizationReason;
        strategy: RelayStrategy;
        decidedAt: Timestamp;
      }>;
    auditEvents: Array<{
        sequence: number;
        eventType: AuditEventType;
        contextVersion: Version;
        relaySessionId?: Uuid;
        relaySessionVersion?: Version;
        actorKind: "APPLICATION" | "SYSTEM";
        data: EventData;
        occurredAt: Timestamp;
      }>;
    enforcement: Array<{
        enforcementEventId: Uuid;
        reason: EnforcementReason;
        status: "PENDING" | "APPLIED";
        contextVersion: Version;
        relaySessionId?: Uuid;
        terminateActiveCalls: boolean;
        affectedPrincipalCount: number;
        attemptCount: number;
        lastErrorCategory?: "TIMEOUT" | "UNAVAILABLE" | "REJECTED" | "INVALID_RESPONSE" | "NOT_CONFIGURED";
        createdAt: Timestamp;
        completedAt?: Timestamp;
      }>;
  };
  /** Keyset-paginated contexts (newest first). */
  export type ContextList = {
    items: Array<CommunicationContext>;
    nextCursor: string | null;
  };
  export type ContextMutationResult = {
    context: CommunicationContext;
    enforcement: Enforcement;
  };
  /** The typed, bounded context policy (never an arbitrary document). Defaults are fail-safe. */
  export type ContextPolicy = {
    /** On revoke, actively terminate protected calls (new authority is denied regardless). */
    terminateActiveCallsOnRevoke?: boolean;
    /** On participant removal, terminate protected calls involving the removed participant; when false they may continue but no new protected call or transfer involving that participant is authorized. */
    terminateActiveCallsOnParticipantRemoval?: boolean;
    /** On suspend, terminate protected calls (new authority is denied regardless). */
    terminateActiveCallsOnSuspend?: boolean;
    /** Whether new calls may be authorized during the completion grace period. */
    graceAllowsNewCalls?: boolean;
  };
  /** Create a Communication Context (Idempotency-Key required). Scope comes only from the authenticated credential; status, version, authorization results, telephone numbers, providers and relay numbers are not inputs. */
  export type CreateContextRequest = {
    externalContextReference: ExternalContextReference;
    participants: Array<SubjectReference>;
    allowedChannels: Array<CommunicationChannel>;
    directionPolicy: DirectionPolicy;
    /** Required (non-empty) with EXPLICIT; refused with BIDIRECTIONAL. */
    directions?: Array<DirectionRequest>;
    startsAt?: Timestamp;
    expiresAt: Timestamp;
    graceExpiresAt?: Timestamp;
    policy?: ContextPolicy;
    /** Default [APP_ONLY]. */
    allowedRelayStrategies?: Array<RelayStrategy>;
  };
  /** Create a Privacy Relay Session of a context (Idempotency-Key required). Everything except relayStrategy is optional and can only NARROW the context (participants, channels, directions, validity, a strategy among the context's allowed strategies). A relay identity or telephone number is never an input. */
  export type CreateSessionRequest = {
    relayStrategy: RelayStrategy;
    participants?: Array<SubjectReference>;
    allowedChannels?: Array<CommunicationChannel>;
    directionPolicy?: DirectionPolicy;
    directions?: Array<DirectionRequest>;
    startsAt?: Timestamp;
    expiresAt?: Timestamp;
    graceExpiresAt?: Timestamp;
  };
  /** BIDIRECTIONAL: any two active participants, both directions. EXPLICIT: only directed edges authorize; A -> B never implies B -> A. */
  export type DirectionPolicy = "BIDIRECTIONAL" | "EXPLICIT";
  /** A directed edge between two subjects; channel restricts it to one channel (absent: every allowed channel). */
  export type DirectionRequest = {
    from: SubjectReference;
    to: SubjectReference;
    channel?: CommunicationChannel;
  };
  /** Active-call enforcement of a mutation (event ids of the durable enforcement jobs it created). */
  export type Enforcement = {
    status: EnforcementState;
    enforcementEventIds: Array<Uuid>;
  };
  /** Why active protected calls are enforced against. */
  export type EnforcementReason = "CONTEXT_REVOKED" | "CONTEXT_SUSPENDED" | "CONTEXT_COMPLETED" | "CONTEXT_EXPIRED" | "PARTICIPANT_REMOVED" | "SESSION_REVOKED" | "SESSION_SUSPENDED" | "SESSION_EXPIRED";
  /** Active-call enforcement state of a mutation: NOT_REQUIRED, PENDING (durably queued; Calling has not confirmed) or APPLIED (Calling confirmed). Never claimed before Calling confirms. */
  export type EnforcementState = "NOT_REQUIRED" | "PENDING" | "APPLIED";
  /** Stable error codes of the Privacy Relay API. AUTHENTICATION_FAILED, INSUFFICIENT_SCOPE and RATE_LIMITED come from the authenticated platform ingress; INTERNAL_* only from internal routes (never relayed to customers). */
  export type ErrorCode = "AUTHENTICATION_FAILED" | "INSUFFICIENT_SCOPE" | "RATE_LIMITED" | "VALIDATION_ERROR" | "NOT_FOUND" | "METHOD_NOT_ALLOWED" | "CONTEXT_NOT_FOUND" | "SESSION_NOT_FOUND" | "CONTEXT_VERSION_CONFLICT" | "SESSION_VERSION_CONFLICT" | "CONTEXT_REFERENCE_CONFLICT" | "CONTEXT_NOT_ACTIVE" | "CONTEXT_EXPIRED" | "CONTEXT_REVOKED" | "CONTEXT_SUSPENDED" | "SESSION_NOT_ACTIVE" | "PARTICIPANT_NOT_AUTHORIZED" | "DIRECTION_NOT_ALLOWED" | "CHANNEL_NOT_ALLOWED" | "STRATEGY_NOT_ALLOWED" | "VALIDITY_NOT_CONTAINED" | "IDEMPOTENCY_CONFLICT" | "PRIVACY_RELAY_DISABLED" | "SERVICE_UNAVAILABLE" | "INTERNAL_ERROR" | "INTERNAL_AUTHENTICATION_FAILED" | "INTERNAL_PERMISSION_DENIED" | "CONTACT_NOT_FOUND" | "CONTACT_VERSION_CONFLICT" | "CONTACT_INVALID" | "CONTACT_ALREADY_EXISTS" | "CONTACT_DISABLED" | "CONTACT_BLOCKED" | "CONTACT_NOT_VERIFIED" | "CONTACT_VERIFICATION_EXPIRED" | "CONTACT_DELEGATION_INVALID" | "CONTACT_SCOPE_DENIED" | "CONTACT_RESOLUTION_DENIED" | "CONTACT_RESOLUTION_GRANT_EXPIRED" | "CONTACT_VAULT_DISABLED" | "RELAY_NUMBER_UNAVAILABLE" | "RELAY_ASSIGNMENT_NOT_FOUND" | "RELAY_MAPPING_NOT_ACTIVE" | "RELAY_MAPPING_AMBIGUOUS" | "RELAY_NUMBER_POOL_DISABLED";
  /** Error response body: stable code, fixed safe message, server request id. Never database errors, foreign-resource existence, tokens or contact data. */
  export type ErrorEnvelope = {
    error: {
      code: ErrorCode;
      message: string;
      requestId: string | null;
    };
  };
  /** Bounded safe evidence: snake_case keys never naming secrets or contact data; ids, versions, counts, statuses. */
  export type EventData = { [key: string]: unknown };
  /** One attempt: timing and normalized outcome only (no provider, route secret or destination). */
  export type EvidenceAttempt = {
    attemptNumber: number;
    startedAt: Timestamp;
    finishedAt: Timestamp | null;
    outcome: "PENDING" | "SUCCEEDED" | "FAILED" | "UNKNOWN" | "ABANDONED";
    unknownOutcome: boolean;
    failureCategory: ("POLICY" | "TARGET_UNAVAILABLE" | "ROUTING" | "TIMEOUT" | "MEDIA" | "NETWORK" | "EXECUTION" | "INTERNAL" | "UNKNOWN") | null;
  };
  /** A Privacy Relay authorization the Call relied on (ids and versions only). */
  export type EvidenceDecision = {
    decisionId: Uuid;
    purpose: "CALL_CREATE" | "CALL_TRANSFER";
    contextVersion: Version;
    relaySessionVersion: Version;
    decidedAt: Timestamp;
  };
  export type EvidenceParticipant = {
    participantId: Uuid;
    principalId: Uuid;
    role: "INITIATOR" | "RECIPIENT";
    /** Union of the participant's session connection intervals. */
    connectedDurationMs: number;
  };
  /** Consumer-defined, opaque, bounded reference of the business relationship (CF Meet never parses it). It can never be contact data: no telephone number, e-mail address or tel / sip / mailto URI. */
  export type ExternalContextReference = string;
  /** Client-chosen key: 1-255 printable ASCII characters without spaces. */
  export type IdempotencyKey = string;
  /** Body of an explicit lifecycle command (suspend, resume, complete, revoke). Idempotency-Key required. */
  export type LifecycleCommandRequest = {
    expectedVersion: Version;
  };
  /** Kind of an authorization subject. */
  export type ParticipantSubjectKind = "PRINCIPAL" | "CONTACT_REFERENCE";
  /** GET /v1/privacy-relay/sessions/{relay_session_id}/evidence: the protected Calls of one Relay Session (newest first, keyset pages of at most 100). */
  export type PrivacyRelayEvidence = {
    relaySessionId: Uuid;
    contextId: Uuid;
    calls: Array<CallEvidence>;
    nextCursor: string | null;
  };
  /** Safe representation of a Privacy Relay Session (NOT a call; one session may authorize many call attempts). relayIdentityBindingRef is opaque and server-owned (never a number, carrier or provider resource). */
  export type PrivacyRelaySession = {
    relaySessionId: Uuid;
    contextId: Uuid;
    version: Version;
    sourceContextVersion: Version;
    status: PrivacyRelaySessionStatus;
    effectiveStatus: PrivacyRelaySessionStatus;
    strategy: RelayStrategy;
    /** Routes the strategy permits that CF Meet can execute today. */
    executableRoutes: Array<CommunicationRoute>;
    directionPolicy: DirectionPolicy;
    participantScope: SnapshotScope;
    channelScope: SnapshotScope;
    directionScope: SnapshotScope;
    participants: Array<{
        participantId: Uuid;
        subjectKind: ParticipantSubjectKind;
        principalId?: Uuid;
        contactReferenceId?: Uuid;
        sourceContextVersion: Version;
      }>;
    allowedChannels: Array<CommunicationChannel>;
    directions: Array<{
        fromParticipantId: Uuid;
        toParticipantId: Uuid;
        channel?: CommunicationChannel;
      }>;
    startsAt: Timestamp;
    expiresAt: Timestamp;
    graceExpiresAt?: Timestamp;
    policyVersion: string;
    policy: ContextPolicy;
    relayIdentityBindingRef?: Uuid;
    createdAt: Timestamp;
    updatedAt: Timestamp;
    suspendedAt?: Timestamp;
    completedAt?: Timestamp;
    revokedAt?: Timestamp;
    expiredAt?: Timestamp;
  };
  /** Lifecycle of a Privacy Relay Session (same graph as contexts); a session never outlives its context's authority. */
  export type PrivacyRelaySessionStatus = "ACTIVE" | "SUSPENDED" | "REVOKED" | "COMPLETED" | "EXPIRED";
  /** Relay strategy: policy, not proof that a route exists. Every strategy permits the application route; the public-network and callback strategies only become executable when relay-number and telephony infrastructure exists. */
  export type RelayStrategy = "APP_ONLY" | "APP_PREFERRED" | "PUBLIC_RELAY_ALLOWED" | "CALLBACK_RELAY_ALLOWED";
  /** Keyset-paginated sessions (newest first). */
  export type SessionList = {
    items: Array<PrivacyRelaySession>;
    nextCursor: string | null;
  };
  export type SessionMutationResult = {
    session: PrivacyRelaySession;
    enforcement: Enforcement;
  };
  /** Whether a relay session follows its context (INHERITED) or was explicitly narrowed (NARROWED). */
  export type SnapshotScope = "INHERITED" | "NARROWED";
  /** Exactly one opaque subject reference: a CF Meet principal id or an opaque ContactReference id. A ContactReference is never a telephone number, e-mail address or SIP URI, and Privacy Relay never resolves it (Contact Vault is a later section). */
  export type SubjectReference = ({
    principalId?: Uuid;
    contactReferenceId?: Uuid;
  }) & ({ principalId: Uuid } | { contactReferenceId: Uuid });
  /** RFC 3339 timestamp (UTC). */
  export type Timestamp = string;
  /** Typed, versioned configuration update (never a status patch or arbitrary merge patch). Absent members are unchanged; participants and directions replace the whole set (participant reassignment keeps the same context). At least one change is required. */
  export type UpdateContextRequest = {
    expectedVersion: Version;
    participants?: Array<SubjectReference>;
    allowedChannels?: Array<CommunicationChannel>;
    directionPolicy?: DirectionPolicy;
    directions?: Array<DirectionRequest>;
    startsAt?: Timestamp;
    expiresAt?: Timestamp;
    graceExpiresAt?: Timestamp;
    policy?: ContextPolicy;
    allowedRelayStrategies?: Array<RelayStrategy>;
  };
  /** Lower-case hyphenated UUID. */
  export type Uuid = string;
  /** Monotonic version (starts at 1, +1 per accepted authority change). */
  export type Version = number;

  /** Typed parameters and response of every REST operation of this domain. */
  export interface Operations {
    /** POST /v1/privacy-relay/contexts/{context_id}/complete — scope privacy.contexts.write; auth PLATFORM_CREDENTIAL; retry IDEMPOTENT */
    completeContext: {
      params: { path: { context_id: string }; body: LifecycleCommandRequest; idempotencyKey?: string };
      response: ContextMutationResult;
    };
    /** POST /v1/privacy-relay/contact-access-grants — scope each requested privacy.contacts.* scope; auth PLATFORM_CREDENTIAL; retry NO_RETRY */
    createContactAccessGrant: {
      params: { body: ContactAccessGrantRequest };
      response: ContactAccessGrantResult;
    };
    /** POST /v1/privacy-relay/contexts — scope privacy.contexts.write; auth PLATFORM_CREDENTIAL; retry IDEMPOTENT */
    createContext: {
      params: { body: CreateContextRequest; idempotencyKey?: string };
      response: ContextMutationResult;
    };
    /** POST /v1/privacy-relay/contexts/{context_id}/sessions — scope privacy.sessions.write; auth PLATFORM_CREDENTIAL; retry NEVER; paid telecom */
    createRelaySession: {
      params: { path: { context_id: string }; body: CreateSessionRequest; idempotencyKey?: string };
      response: SessionMutationResult;
    };
    /** GET /v1/privacy-relay/contexts/{context_id} — scope privacy.contexts.read; auth PLATFORM_CREDENTIAL; retry SAFE */
    getContext: {
      params: { path: { context_id: string } };
      response: CommunicationContext;
    };
    /** GET /v1/privacy-relay/contexts/{context_id}/evidence — scope privacy.contexts.read; auth PLATFORM_CREDENTIAL; retry SAFE */
    getContextEvidence: {
      params: { path: { context_id: string } };
      response: ContextEvidence;
    };
    /** GET /v1/privacy-relay/sessions/{relay_session_id} — scope privacy.sessions.read; auth PLATFORM_CREDENTIAL; retry SAFE */
    getRelaySession: {
      params: { path: { relay_session_id: string } };
      response: PrivacyRelaySession;
    };
    /** GET /v1/privacy-relay/sessions/{relay_session_id}/evidence — scope privacy.evidence.read; auth PLATFORM_CREDENTIAL; retry SAFE */
    getRelaySessionCallEvidence: {
      params: { path: { relay_session_id: string }; query?: { limit?: number; cursor?: string } };
      response: PrivacyRelayEvidence;
      item: NonNullable<(PrivacyRelayEvidence)["calls"]>[number];
    };
    /** GET /v1/privacy-relay/contexts — scope privacy.contexts.read; auth PLATFORM_CREDENTIAL; retry SAFE */
    listContexts: {
      params: { query?: { limit?: number; cursor?: string; status?: CommunicationContextStatus; externalContextReference?: ExternalContextReference } };
      response: ContextList;
      item: NonNullable<(ContextList)["items"]>[number];
    };
    /** GET /v1/privacy-relay/sessions — scope privacy.sessions.read; auth PLATFORM_CREDENTIAL; retry SAFE */
    listRelaySessions: {
      params: { query?: { limit?: number; cursor?: string; status?: PrivacyRelaySessionStatus; contextId?: Uuid } };
      response: SessionList;
      item: NonNullable<(SessionList)["items"]>[number];
    };
    /** POST /v1/privacy-relay/contexts/{context_id}/resume — scope privacy.contexts.write; auth PLATFORM_CREDENTIAL; retry IDEMPOTENT */
    resumeContext: {
      params: { path: { context_id: string }; body: LifecycleCommandRequest; idempotencyKey?: string };
      response: ContextMutationResult;
    };
    /** POST /v1/privacy-relay/sessions/{relay_session_id}/resume — scope privacy.sessions.write; auth PLATFORM_CREDENTIAL; retry IDEMPOTENT */
    resumeSession: {
      params: { path: { relay_session_id: string }; body: LifecycleCommandRequest; idempotencyKey?: string };
      response: SessionMutationResult;
    };
    /** POST /v1/privacy-relay/contexts/{context_id}/revoke — scope privacy.contexts.write; auth PLATFORM_CREDENTIAL; retry IDEMPOTENT */
    revokeContext: {
      params: { path: { context_id: string }; body: LifecycleCommandRequest; idempotencyKey?: string };
      response: ContextMutationResult;
    };
    /** POST /v1/privacy-relay/sessions/{relay_session_id}/revoke — scope privacy.sessions.write; auth PLATFORM_CREDENTIAL; retry IDEMPOTENT */
    revokeSession: {
      params: { path: { relay_session_id: string }; body: LifecycleCommandRequest; idempotencyKey?: string };
      response: SessionMutationResult;
    };
    /** POST /v1/privacy-relay/contexts/{context_id}/suspend — scope privacy.contexts.write; auth PLATFORM_CREDENTIAL; retry IDEMPOTENT */
    suspendContext: {
      params: { path: { context_id: string }; body: LifecycleCommandRequest; idempotencyKey?: string };
      response: ContextMutationResult;
    };
    /** POST /v1/privacy-relay/sessions/{relay_session_id}/suspend — scope privacy.sessions.write; auth PLATFORM_CREDENTIAL; retry IDEMPOTENT */
    suspendSession: {
      params: { path: { relay_session_id: string }; body: LifecycleCommandRequest; idempotencyKey?: string };
      response: SessionMutationResult;
    };
    /** PATCH /v1/privacy-relay/contexts/{context_id} — scope privacy.contexts.write; auth PLATFORM_CREDENTIAL; retry IDEMPOTENT */
    updateContext: {
      params: { path: { context_id: string }; body: UpdateContextRequest; idempotencyKey?: string };
      response: ContextMutationResult;
    };
  }
}

export namespace Sms {
  /** Estimated / provider-confirmed cost in minor units. */
  export type Cost = {
    estimatedMinor: number | null;
    confirmedMinor: number | null;
    currency: string;
  };
  export type Direction = "OUTBOUND" | "INBOUND";
  /** GSM-7 (160 / 153 septets per segment; extension characters count two) or UCS-2 (70 / 67 UTF-16 units). */
  export type Encoding = "GSM7" | "UCS2";
  /** The SMS Gateway error envelope. */
  export type Error = {
    /** One error. */
    error: {
      code: "VALIDATION_ERROR" | "AUTHENTICATION_FAILED" | "INSUFFICIENT_SCOPE" | "NOT_FOUND" | "METHOD_NOT_ALLOWED" | "PAYLOAD_TOO_LARGE" | "RATE_LIMITED" | "INTERNAL_AUTHENTICATION_FAILED" | "INTERNAL_PERMISSION_DENIED" | "CALLBACK_REJECTED" | "IDEMPOTENCY_KEY_REQUIRED" | "IDEMPOTENCY_KEY_REUSED" | "CONTENT_TOO_LONG" | "SMS_BLOCKED" | "CONFLICT" | "NUMBERING_UNAVAILABLE" | "PROVIDER_UNAVAILABLE" | "SERVICE_UNAVAILABLE" | "INTERNAL_ERROR";
      message: string;
      requestId: RequestId | null;
      reason?: string;
      messageId?: Uuid;
    };
  };
  /** One message (inbound or outbound). `content` is the plaintext for the owning environment only (null once purged by retention); the remote party is masked; no provider identifier. */
  export type Message = {
    messageId: Uuid;
    direction: Direction;
    status: Status;
    numberResourceId: Uuid;
    threadId: Uuid;
    remote: RemoteParty;
    content: string | null;
    contentPurged: boolean;
    encoding: Encoding;
    segmentCount: number;
    characterCount: number;
    principalId: Uuid | null;
    routing: Routing | null;
    failureCode: string | null;
    blockedReason: string | null;
    cost: Cost | null;
    createdAt: string;
    expiresAt: string | null;
    submittedAt: string | null;
    deliveredAt: string | null;
    receivedAt: string | null;
    failedAt: string | null;
  };
  /** A page of messages, newest first. */
  export type MessagePage = {
    messages: Array<Message>;
    nextCursor: string | null;
  };
  /** A recipient block (masked). */
  export type OptOut = {
    remote: RemoteParty;
    numberResourceId: Uuid | null;
    reason: "STOP_KEYWORD" | "CUSTOMER_REQUEST" | "ABUSE";
    createdAt: string;
  };
  /** POST /v1/sms/opt-outs (scope sms.send): the customer blocks a recipient for one number (or every number of the environment). */
  export type OptOutRequest = {
    to: string;
    numberResourceId?: Uuid;
  };
  /** The remote party (masked only). */
  export type RemoteParty = {
    /** The remote party, masked: `+***` and the last four digits. The full number is never returned. */
    masked: string;
  };
  /** Server-generated identifier of one request / one service hop. */
  export type RequestId = string;
  /** Numbering's SMS routing target of an inbound message (opaque CF Meet reference). */
  export type Routing = {
    targetKind: string;
    targetRef: Uuid;
  };
  /** POST /v1/sms/messages (scope sms.send, Idempotency-Key required): send ONE message from a Number Resource the environment actively owns (Numbering issues and the gateway consumes a single-use SMS_SENDER grant — an arbitrary sender id is impossible). The recipient is either `to` (E.164) or the remote party of `threadId`. */
  export type SendMessageRequest = ({
    /** The sender. */
    from: {
      numberResourceId: Uuid;
    };
    to?: string;
    threadId?: Uuid;
    text: string;
    /** The principal the message is sent for (required for personal / professional numbers; must be ACTIVE in the environment). */
    principalId?: Uuid;
    validitySeconds?: number;
  }) & ({ to: string } | { threadId: Uuid });
  /** Transport status. UNKNOWN: the provider may hold the message; it is never resubmitted, only provider evidence resolves it. */
  export type Status = "REQUESTED" | "AUTHORIZED" | "SUBMITTING" | "SUBMITTED" | "DELIVERED" | "RECEIVED" | "FAILED" | "UNKNOWN" | "EXPIRED";
  /** A transport thread: the messages between one Number Resource and one remote party. A transport index, not a conversation. */
  export type Thread = {
    threadId: Uuid;
    numberResourceId: Uuid;
    remote: RemoteParty;
    messageCount: number;
    lastMessageAt: string;
    createdAt: string;
  };
  /** A page of threads, most recent first. */
  export type ThreadPage = {
    threads: Array<Thread>;
    nextCursor: string | null;
  };
  /** Lower-case hyphenated UUID. */
  export type Uuid = string;

  /** Typed parameters and response of every REST operation of this domain. */
  export interface Operations {
    /** POST /v1/sms/opt-outs; auth PLATFORM_CREDENTIAL; retry NO_RETRY */
    createOptOut: {
      params: { body: OptOutRequest };
      response: OptOut;
    };
    /** GET /v1/sms/messages/{messageId}; auth PLATFORM_CREDENTIAL; retry SAFE */
    getMessage: {
      params: { path: { messageId: Uuid } };
      response: Message;
    };
    /** GET /v1/sms/messages; auth PLATFORM_CREDENTIAL; retry SAFE */
    listMessages: {
      params: { query?: { numberResourceId?: Uuid; direction?: Direction; cursor?: string; limit?: number } };
      response: MessagePage;
      item: NonNullable<(MessagePage)["messages"]>[number];
    };
    /** GET /v1/sms/threads/{threadId}/messages; auth PLATFORM_CREDENTIAL; retry SAFE */
    listThreadMessages: {
      params: { path: { threadId: Uuid }; query?: { cursor?: string; limit?: number } };
      response: MessagePage;
      item: NonNullable<(MessagePage)["messages"]>[number];
    };
    /** GET /v1/sms/threads; auth PLATFORM_CREDENTIAL; retry SAFE */
    listThreads: {
      params: { query?: { numberResourceId?: Uuid; cursor?: string; limit?: number } };
      response: ThreadPage;
      item: NonNullable<(ThreadPage)["threads"]>[number];
    };
    /** POST /v1/sms/messages; auth PLATFORM_CREDENTIAL; retry NEVER; paid telecom */
    sendMessage: {
      params: { body: SendMessageRequest; idempotencyKey?: string };
      response: Message;
    };
  }
}

/** Operation types of every domain, keyed like `OperationSpec.domain`. */
export interface DomainOperations {
  calling: Calling.Operations;
  "developer-platform": DeveloperPlatform.Operations;
  gateway: Gateway.Operations;
  meetings: Meetings.Operations;
  messaging: Messaging.Operations;
  numbering: Numbering.Operations;
  "privacy-relay": PrivacyRelay.Operations;
  sms: Sms.Operations;
}
